(r, big) => {
  const nd = v => ({ v, L: null, R: null });
  const put = (t, x, b) => { if (!t) return x; let c = t; for (;;) { const k = r.bool(b) ? "L" : "R"; if (!c[k]) { c[k] = x; return t; } c = c[k]; } };
  const rnd = (n, V, b) => { let t = null; for (let i = 0; i < n; i++) t = put(t, nd(V()), b); return t; };
  const ser = t => { const o = [], q = [t]; for (let i = 0; i < q.length; i++) { const x = q[i]; if (x) { o.push(x.v); q.push(x.L, x.R); } else o.push(null); } while (o.length && o[o.length - 1] === null) o.pop(); return o; };
  const V = () => r.int(-5, 5);
  // a tree that is balanced by construction: children are h-1 and h-1, or h-1 and h-2
  const bal = h => { if (h <= 0) return null; const t = nd(V()); const d = r.int(0, 2); t.L = bal(d === 1 ? h - 2 : h - 1); t.R = bal(d === 2 ? h - 2 : h - 1); return t; };
  // hang a 2-node chain on a random empty slot: often breaks balance somewhere deep, sometimes not
  const dent = t => { const a = nd(V()); a.L = nd(V()); return put(t, a, 0.5); };
  if (big) { let t; do t = bal(17); while (ser(t).length > 40000); return [ser(r.bool() ? dent(t) : t)]; }
  if (r.bool(0.3)) return [ser(rnd(r.int(0, 10), V, r.pick([0.5, 0.2, 0.8])))];
  const t = bal(r.int(0, 4));
  return [ser(r.bool() ? dent(t) : t)];
}

